WITH selected AS MATERIALIZED (
SELECT e.event_id,e.calendar_id,CAST(e.start_at AS TEXT) AS start_key,e.start_at,e.end_at,e.start_date,e.end_date,e.payload_json
FROM cached_events e JOIN calendars c ON c.id=e.calendar_id JOIN connections conn ON conn.id=c.connection_id
WHERE e.calendar_id IN (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) AND c.can_read=? AND conn.status=? AND e.deleted=? AND e.rowid IN (SELECT rowid FROM cached_events WHERE calendar_id IN (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) AND deleted=? AND start_at IS NOT NULL AND start_at<? AND end_at>? UNION SELECT rowid FROM cached_events WHERE calendar_id IN (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) AND deleted=? AND start_date IS NOT NULL AND start_date<? AND end_date>?) AND (e.start_at IS NULL OR (e.start_at<? AND e.end_at>?)) AND COALESCE(CASE WHEN json_valid(e.payload_json) THEN json_extract(e.payload_json, '$.instance_kind') ELSE '' END,'')<>'seriesMaster' ORDER BY e.start_at IS NULL,e.start_at,CASE WHEN e.start_at IS NULL THEN e.start_date END,e.event_id,e.calendar_id LIMIT ?), projected AS MATERIALIZED (
SELECT e.event_id,e.calendar_id,e.start_key,e.start_at,e.end_at,e.start_date,e.end_date,
(((e.event_id IS NULL OR (typeof(e.event_id)='text' AND length(CAST(e.event_id AS BLOB))<=1024)) AND (e.calendar_id IS NULL OR (typeof(e.calendar_id)='text' AND length(CAST(e.calendar_id AS BLOB))<=1024)) AND (e.start_at IS NULL OR (typeof(e.start_at)='text' AND length(CAST(e.start_at AS BLOB))<=128)) AND (e.end_at IS NULL OR (typeof(e.end_at)='text' AND length(CAST(e.end_at AS BLOB))<=128)) AND (e.start_date IS NULL OR (typeof(e.start_date)='text' AND length(CAST(e.start_date AS BLOB))<=128)) AND (e.end_date IS NULL OR (typeof(e.end_date)='text' AND length(CAST(e.end_date AS BLOB))<=128)) AND e.event_id IS NOT NULL AND e.event_id<>'' AND e.calendar_id IS NOT NULL AND e.calendar_id<>'') AND json_valid(e.payload_json)) AS scalar_ok,CASE WHEN ((e.event_id IS NULL OR (typeof(e.event_id)='text' AND length(CAST(e.event_id AS BLOB))<=1024)) AND (e.calendar_id IS NULL OR (typeof(e.calendar_id)='text' AND length(CAST(e.calendar_id AS BLOB))<=1024)) AND (e.start_at IS NULL OR (typeof(e.start_at)='text' AND length(CAST(e.start_at AS BLOB))<=128)) AND (e.end_at IS NULL OR (typeof(e.end_at)='text' AND length(CAST(e.end_at AS BLOB))<=128)) AND (e.start_date IS NULL OR (typeof(e.start_date)='text' AND length(CAST(e.start_date AS BLOB))<=128)) AND (e.end_date IS NULL OR (typeof(e.end_date)='text' AND length(CAST(e.end_date AS BLOB))<=128)) AND e.event_id IS NOT NULL AND e.event_id<>'' AND e.calendar_id IS NOT NULL AND e.calendar_id<>'') AND json_valid(e.payload_json) THEN json_object('title',json(e.payload_json->'$.title'),'start',json(e.payload_json->'$.start'),'end',json(e.payload_json->'$.end'),'status',json(e.payload_json->'$.status')) ELSE NULL END AS summary_json FROM selected e) SELECT CASE WHEN scalar_ok THEN event_id ELSE NULL END,CASE WHEN scalar_ok THEN calendar_id ELSE NULL END,CASE WHEN scalar_ok THEN start_key ELSE NULL END,CASE WHEN scalar_ok THEN start_at ELSE NULL END,CASE WHEN scalar_ok THEN end_at ELSE NULL END,CASE WHEN scalar_ok THEN start_date ELSE NULL END,CASE WHEN scalar_ok THEN end_date ELSE NULL END,CASE WHEN scalar_ok AND length(CAST(summary_json AS BLOB))<=32768 THEN summary_json ELSE NULL END,CASE WHEN scalar_ok THEN 0 ELSE 1 END
FROM projected ORDER BY start_at IS NULL,start_at,CASE WHEN start_at IS NULL THEN start_date END,event_id,calendar_id